properties.query:
let baselineWindow = 24h;
let alertWindow = 10m;
let zThreshold = 3.0;
let KnownGCS = _GetWatchlist('C2_Whitelisted_GCS_List') | project GCS_IP;
let MavsecAnomaly =
    UAVMavsec_CL
    | where TimeGenerated > ago(baselineWindow)
    | make-series AvgUnsigned=avg(UnsignedCount) on TimeGenerated step 5m by UAVId
    | extend (UA, US, UB) = series_decompose_anomalies(AvgUnsigned, zThreshold)
    | project UAVId, TimeGenerated, AvgUnsigned, UA
    | mv-expand TimeGenerated to typeof(datetime), AvgUnsigned to typeof(double), UA to typeof(double)
    | where TimeGenerated > ago(alertWindow) and UA == 1
    | project TimeGenerated, UAVId, AvgUnsigned;
let FailedAlert =
    UAVMavsec_CL
    | where TimeGenerated > ago(alertWindow)
    | where FailedCount > 0
    | project TimeGenerated, UAVId, FailedCount;
let SuspectConn =
    UAVDatalinkConn_CL
    | where TimeGenerated > ago(alertWindow)
    | where PeerIp !in (KnownGCS)
    | summarize ConnCount=count() by PeerIp;
union
    (MavsecAnomaly | extend TriggerReason = strcat("MAVLink_무서명급증_zscore_UAVId:", UAVId), Severity = "High"),
    (FailedAlert | extend TriggerReason = strcat("MAVLink_서명검증_실패_", tostring(FailedCount), "건"), Severity = "High")
| project TimeGenerated, UAVId, TriggerReason, Severity
| order by TimeGenerated desc
